@import url('https://fonts.googleapis.com/css2?family=Boogaloo&family=Caveat:wght@600;700&family=Unbounded:wght@600;700&display=swap');

:root{color-scheme:light}body{margin:0;padding:0;font:14px -apple-system,BlinkMacSystemFont,sans-serif;background:#FCFBF8;color:#141413}img{max-width:100%}[hidden]:not([hidden=until-found i]){display:none!important}

/* ============================================================
   DEMLEME v3 — muted editorial brand: parchment ground, aged
   copper + dusty plum + muted gold accents, matte-black ink,
   Fraunces/Karla type system, hand-drawn "teabag+mic" and
   "sofra" brand marks.
   ============================================================ */
/* NOTE: 'Strenuous' is not a Google Font and could not be fetched in this environment.
   Boogaloo (free, Google Fonts, 1960s/70s groovy display style) stands in for it below.
   Send the actual Strenuous .ttf/.otf files and this gets swapped in directly. */






:root{
  --cream:      #FCFBF8;
  --cream-deep: #F1ECDF;
  --paper:      #FFFFFF;
  --butter:     #D9B65C;
  --butter-deep:#B8903A;
  --lav:        #A896AC;
  --lav-deep:   #6B5470;
  --rust:       #A8552A;
  --rust-deep:  #7A3D1C;
  --green:      #3B5D42;
  --green-deep: #1F3A26;
  --teal:       #4C7A8C;
  --lime:       #B8C77A;
  --lime-deep:  #8FA050;
  --ink:        #17130F;
  --ink-fixed:  #17130F;
  --cream-fixed:#F3EEE1;
  --ink-soft:   rgba(22,19,14,.68);
  --ink-faint:  rgba(22,19,14,.46);
  --ink-soft-fixed: rgba(22,19,14,.68);
  --ink-faint-fixed:rgba(22,19,14,.46);
  --line:       rgba(22,19,14,.12);
  --on-dark-soft: rgba(243,238,225,.72);
  --on-dark-faint:rgba(243,238,225,.48);
  --shadow-sm:  0 8px 18px -10px rgba(22,19,14,.22);
  --shadow-md:  0 22px 44px -20px rgba(22,19,14,.26);
  --shadow-lg:  0 40px 80px -28px rgba(22,19,14,.32);
  --font-display: 'Boogaloo', 'Fraunces', Georgia, 'Times New Roman', serif;
  --font-body: 'Kodchasan', system-ui, -apple-system, sans-serif;
  --font-script: 'Caveat', cursive;
  --font-mark: 'Unbounded', var(--font-display);
  --pad: clamp(20px, 5vw, 64px);
  --wrap: 1280px;
  --ease-premium: cubic-bezier(.22,1,.36,1);
  --duration-fast: 220ms;
  --duration-base: 500ms;
  --duration-slow: 900ms;
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth; overflow-x:hidden; max-width:100%;}
:focus-visible{ outline:2px solid var(--rust); outline-offset:3px; border-radius:6px; }
.nav-icon-btn:focus-visible, .btn-circle:focus-visible{ outline-offset:2px; }
@media (prefers-reduced-motion: reduce){ :focus-visible{ transition:none; } }
body{
  margin:0; background:var(--cream); color:var(--ink); font-family:var(--font-body);
  -webkit-font-smoothing:antialiased; overflow-x:hidden;
}
img{max-width:100%; display:block;}
a{color:inherit; text-decoration:none;}
button{font:inherit; color:inherit; background:none; border:none; cursor:pointer;}
h1,h2,h3{font-family:var(--font-display); margin:0; letter-spacing:-.01em;}
p{margin:0;}
.eyebrow{ font-size:.78rem; font-weight:700; letter-spacing:.14em; text-transform:uppercase; color:var(--rust); margin:0 0 10px; }
.hero-live-badge{ display:inline-flex; align-items:center; gap:8px; background:var(--ink); color:var(--cream-fixed); font-size:.72rem; font-weight:800; letter-spacing:.08em; text-transform:uppercase; padding:8px 16px 8px 12px; border-radius:999px; margin-bottom:18px; box-shadow:var(--shadow-sm); }
.hero-live-dot{ width:8px; height:8px; border-radius:50%; background:#ff5b45; flex-shrink:0; animation:heroLivePulse 1.6s ease-in-out infinite; }
@keyframes heroLivePulse{ 0%,100%{ transform:scale(1); box-shadow:0 0 0 0 rgba(255,91,69,.55); } 50%{ transform:scale(1.15); box-shadow:0 0 0 5px rgba(255,91,69,0); } }
@media (prefers-reduced-motion: reduce){ .hero-live-dot{ animation:none; } }

.wrap{ max-width:var(--wrap); margin:0 auto; padding:0 var(--pad); }
.btn{ display:inline-flex; align-items:center; gap:9px; padding:15px 26px; border-radius:999px; font-weight:700; font-size:.92rem; transition:transform .3s cubic-bezier(.2,.8,.2,1), background .25s, color .25s, border-color .25s; white-space:nowrap; }
.btn svg{ width:16px; height:16px; flex-shrink:0; }
.btn-ink{ background:var(--ink); color:var(--paper); }
.btn-ink:hover{ background:var(--rust-deep); transform:translateY(-2px); }
.btn-outline{ background:transparent; color:var(--ink); border:1.5px solid var(--ink); }
.btn-outline:hover{ background:var(--ink); color:var(--paper); transform:translateY(-2px); }
.btn:active{ transform:scale(.98); transition-duration:.12s; }
.btn-circle{ width:46px; height:46px; border-radius:50%; display:flex; align-items:center; justify-content:center; background:var(--paper); border:1px solid var(--line); box-shadow:var(--shadow-sm); transition:background .25s, transform .3s, color .25s; flex-shrink:0; }
.btn-circle:hover{ background:var(--ink); color:var(--paper); transform:translateY(-2px); }
.btn-circle:active{ transform:scale(.92); transition-duration:.12s; }
.btn-circle svg{ width:17px; height:17px; }
.btn-circle.solid{ background:var(--ink); color:var(--paper); }
.btn-circle.solid:hover{ background:var(--rust-deep); }
@media (prefers-reduced-motion: reduce){ .btn:active, .btn-circle:active{ transform:none; } }
[hidden]{ display:none !important; }
.reveal{ opacity:0; transform:translateY(32px); filter:blur(5px); transition:opacity .55s cubic-bezier(.2,.8,.2,1), transform .6s cubic-bezier(.16,.9,.2,1), filter .55s cubic-bezier(.2,.8,.2,1); }
.reveal.in{ opacity:1; transform:translateY(0); filter:blur(0); }
.reveal-scale{ opacity:0; transform:translateY(22px) scale(.94); filter:blur(4px); transition:opacity .5s ease, transform .55s cubic-bezier(.2,.8,.2,1), filter .5s ease; }
.reveal-scale.in{ opacity:1; transform:translateY(0) scale(1); filter:blur(0); }
@media (prefers-reduced-motion: reduce){ html{ scroll-behavior:auto; } .reveal,.reveal-scale{ transition:none; opacity:1; transform:none; filter:none; } }
.split-heading{ perspective:700px; }
.split-heading .word{ overflow:visible; }
.split-heading .char{ will-change:transform, opacity; }

/* brand marks: hand-drawn teabag+mic + sofra table illustrations, 4 colorways */
.mk{ background-repeat:no-repeat; background-position:center; background-size:contain; display:inline-block; }
.mk-icon-yellow{ background-image:url('data:image/png;base64,'); }
.mk-icon-green{ background-image:url('data:image/png;base64,'); }
.mk-icon-rust{ background-image:url('data:image/png;base64,'); }
.mk-icon-blue{ background-image:url('data:image/png;base64,'); }
.mk-sofra-green{ background-image:url('data:image/png;base64,'); }
.mk-sofra-teal{ background-image:url('data:image/png;base64,'); }
.mk-sofra-rust{ background-image:url('data:image/png;base64,'); }
.mk-glass-rust{ background-image:url('data:image/png;base64,'); }


/* ---------------- NAV ---------------- */
.site-nav{
  position:sticky; top:0; z-index:1000; display:flex; align-items:center; justify-content:space-between;
  padding:20px var(--pad); background:rgba(243,238,225,0); backdrop-filter:blur(0px); border-bottom:1px solid transparent;
  transition:background .45s var(--ease-premium, ease), backdrop-filter .45s var(--ease-premium, ease), border-color .35s, box-shadow .35s;
}
.site-nav.scrolled{
  background:rgba(243,238,225,.86); backdrop-filter:blur(14px); -webkit-backdrop-filter:blur(14px);
  border-color:var(--line); box-shadow:0 8px 24px -18px rgba(22,19,14,.3);
}
html.dark-mode .site-nav:not(.scrolled){ background:rgba(32,27,20,0); }
.nav-logo{ display:flex; align-items:center; }
.nav-logo-img{ display:block; height:20px; width:auto; }
html.dark-mode .nav-logo-img{ filter:invert(1); }
.nav-links{ list-style:none; display:flex; gap:34px; margin:0; padding:0; }
.nav-links a{ font-weight:600; font-size:.92rem; padding-bottom:5px; border-bottom:2px solid transparent; transition:border-color .25s, color .25s; }
.nav-links a:hover{ color:var(--rust); }
.nav-links a.active{ color:var(--rust); border-color:var(--rust); }
.nav-icons{ display:flex; align-items:center; gap:21px; }
.nav-icon-btn{ width:29px; height:29px; display:flex; align-items:center; justify-content:center; color:var(--ink); transition:color .2s, transform .2s; }
.nav-icon-btn svg{ width:100%; height:100%; }
.nav-icon-btn:hover{ color:var(--rust); transform:translateY(-1px); }
#cartBtn{
  width:50px; height:50px; border-radius:50%; flex-shrink:0;
  background:var(--ink-fixed); color:var(--cream-fixed);
  box-shadow:0 6px 16px -8px rgba(22,19,14,.55);
  transition:background .25s, transform .25s, box-shadow .25s;
}
#cartBtn svg{ width:22px; height:22px; }
#cartBtn:hover{ background:var(--rust-deep); color:var(--cream-fixed); transform:translateY(-2px) scale(1.05); box-shadow:0 10px 20px -8px rgba(122,61,28,.55); }
@media (prefers-reduced-motion: reduce){ #cartBtn:hover, .nav-icon-btn:hover{ transform:none; } }
.nav-cart-btn{ position:relative; }
.nav-cart-badge{
  position:absolute; top:-9px; right:-11px; background:var(--ink-fixed); color:var(--butter); font-size:.62rem; font-weight:800;
  min-width:17px; height:17px; border-radius:999px; display:flex; align-items:center; justify-content:center; padding:0 3px;
}
.nav-hamburger{ display:none; }
@media (max-width:900px){
  .nav-links{ display:none; }
  .nav-hamburger{ display:flex; width:24px; height:24px; }
  .nav-hamburger svg{ width:100%; height:100%; }
  /* the icon row (theme + fav + cart + search + Instagram + hamburger) is too wide for
     narrow screens and was pushing the hamburger button off the right edge entirely,
     making the main menu unreachable on mobile. Instagram is already reachable from the
     drawer footer, so drop that copy here and tighten the gap to keep every remaining
     icon -- especially the hamburger -- inside the viewport on small phones too. */
  .nav-icons{ gap:12px; }
  .nav-icons > a.nav-icon-btn{ display:none; }
}
@media (max-width:380px){
  .nav-icons{ gap:8px; }
  .nav-icons .theme-toggle{ display:none; }
}

/* ---------------- HERO ---------------- */
.hero{ position:relative; overflow:hidden; }
/* real photo used as a scroll-parallax depth layer behind the hero copy --
   oversized + cropped by .hero's own overflow:hidden, with a soft cream
   vignette so headline/stat-card/glass illustration stay fully legible. */
.hero-photo-layer{ position:absolute; inset:-18% -10% -8% -10%; z-index:0; border-radius:0 0 48px 48px;
  background-size:cover; background-position:center 40%; opacity:.34; filter:saturate(1.05) contrast(1.02);
  pointer-events:none; animation:heroPhotoIn 1.5s var(--ease-premium,ease) both; }
@keyframes heroPhotoIn{ from{ opacity:0; filter:saturate(1.05) contrast(1.02) blur(10px); } to{ opacity:.34; filter:saturate(1.05) contrast(1.02) blur(0); } }
.hero-photo-layer::after{ content:''; position:absolute; inset:0;
  background:linear-gradient(180deg, var(--cream) 0%, rgba(243,238,225,.5) 26%, rgba(243,238,225,.1) 52%, rgba(243,238,225,.58) 80%, var(--cream) 100%); }
@media (max-width:640px){ .hero-photo-layer{ opacity:.24; } }
@media (prefers-reduced-motion: reduce){ .hero-photo-layer{ translate:none !important; animation:none !important; } }
/* a still, single-tone warm wash -- adds a little depth behind the copy/cards without the
   multi-hue rotating gradient this used to run (that read as the background cycling through
   colors, which didn't land well). */
.hero::after{
  content:''; position:absolute; inset:-25%; pointer-events:none;
  background:radial-gradient(circle at 30% 24%, rgba(217,182,92,.14), transparent 62%);
  mix-blend-mode:soft-light;
}
.hero-head-row{ position:relative; z-index:1; max-width:var(--wrap); margin:0 auto; display:flex; align-items:center; gap:40px; flex-wrap:wrap; }
.hero-head{ flex:1 1 420px; max-width:640px; }
.hero-head h1{ font-size:clamp(3rem,7.6vw,6.6rem); line-height:.98; font-weight:800; letter-spacing:-.01em; margin-bottom:26px; }
.hero-head h1 .script{ font-family:var(--font-display); font-style:italic; font-weight:600; color:var(--lav-deep); }

/* -------- cycling hero headline: "İyi bir [icon] sohbet, zamanla [icon] demlenir." -------- */
.hero-head h1.hero-cycle-head{ line-height:1.32; }
.hcl-line{ display:block; }
.hero-cycle-slot{
  position:relative; display:inline-flex; align-items:center; justify-content:center;
  width:.82em; height:.82em; vertical-align:-.16em; margin:0 .05em; border-radius:50%;
  background:var(--paper); border:1.5px solid var(--line); box-shadow:var(--shadow-sm); overflow:hidden;
}
.hcs-icon{
  position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
  opacity:0; transform:scale(.6) rotate(-8deg);
  transition:opacity .5s cubic-bezier(.2,.8,.2,1), transform .5s cubic-bezier(.34,1.4,.4,1);
}
.hcs-icon.is-active{ opacity:1; transform:scale(1) rotate(0deg); }
.hcs-icon svg{ width:60%; height:60%; }
@media (prefers-reduced-motion: reduce){ .hcs-icon{ transition:none; } }
@media (max-width:640px){ .hero-cycle-slot{ width:.78em; height:.78em; } }

/* -------- ticker bar: thin scrolling strip above the nav -------- */
.ticker-bar{ background:var(--ink-fixed); color:var(--cream-fixed); overflow:hidden; white-space:nowrap; position:relative; }
.ticker-track{ display:inline-flex; width:max-content; animation:tickerScroll 30s linear infinite; will-change:transform; }
.ticker-item{
  display:inline-flex; align-items:center; font-size:.68rem; font-weight:700; letter-spacing:.07em;
  padding:8px 22px; white-space:nowrap; border-left:1px solid rgba(255,252,246,.22);
  font-variant-numeric:tabular-nums;
}
.ticker-track > .ticker-item:first-child{ border-left:none; }
@keyframes tickerScroll{ from{ transform:translateX(0); } to{ transform:translateX(-50%); } }
@media (prefers-reduced-motion: reduce){ .ticker-track{ animation:none; overflow-x:auto; } }
.hero-sub{ font-size:1.02rem; color:var(--ink-soft); max-width:42ch; margin:20px 0 28px; line-height:1.6; }
.hero-ctas{ display:flex; gap:14px; flex-wrap:wrap; margin:22px 0 22px; }
.hero-follow{ display:flex; align-items:center; gap:12px; }
.hero-follow-avatars{ display:flex; }
.hero-follow-avatars .avatar{ width:34px; height:34px; border-radius:50%; border:2.5px solid var(--cream); margin-left:-10px; display:flex; align-items:center; justify-content:center; font-size:.68rem; font-weight:800; color:var(--paper); }
.hero-follow-avatars .avatar:first-child{ margin-left:0; }
.hero-follow-text{ font-size:.86rem; font-weight:700; }
.hero-follow-text span{ display:block; font-size:.72rem; font-weight:600; color:var(--ink-faint); }

@media (max-width:980px){
  .hero-head{ max-width:none; }
}


/* ---------------- AUTO-ROTATING HIGHLIGHTS (videos + products mixed) ---------------- */
.highlights-sec{ padding:6px 0 64px; overflow:hidden; position:relative; }
.highlights-head{ max-width:var(--wrap); margin:0 auto 24px; padding:0 var(--pad); display:flex; align-items:center; justify-content:space-between; gap:16px; flex-wrap:wrap; }
.highlights-head p.eyebrow{ margin-bottom:4px; }
.highlights-head h2{ font-size:clamp(1.4rem,2.6vw,1.9rem); font-weight:800; }
.highlights-nav-btns{ display:flex; gap:10px; flex-shrink:0; }
/* small real-photo accent between the section heading and its nav buttons --
   ties the mixed video/product strip to an actual sofra moment, and doubles
   as a clearly-visible parallax layer (sharp photo detail vs. the soft blobs). */
.highlights-photo{ flex:0 0 auto; width:120px; height:78px; border-radius:14px; overflow:hidden; position:relative;
  background-size:cover; background-position:center; box-shadow:var(--shadow-sm); border:3px solid var(--paper);
  transform:rotate(-2deg); }
.highlights-photo::after{ content:''; position:absolute; inset:0; border-radius:11px; box-shadow:inset 0 0 0 1px rgba(22,19,14,.08); }
@media (max-width:640px){ .highlights-photo{ width:88px; height:60px; } }
@media (prefers-reduced-motion: reduce){ .highlights-photo{ translate:none !important; } }
.highlights-track-wrap{ max-width:100%; -webkit-mask-image:linear-gradient(90deg,transparent,black 6%,black 94%,transparent); mask-image:linear-gradient(90deg,transparent,black 6%,black 94%,transparent); }
.highlights-track{ display:flex; gap:20px; padding:0 var(--pad) 8px; overflow-x:auto; scroll-snap-type:x proximity; scrollbar-width:none; }
.highlights-track::-webkit-scrollbar{ display:none; }
@media (prefers-reduced-motion: reduce){ .highlights-track{ scroll-behavior:auto; } }
/* True scroll-linked horizontal panel scroll (desktop, motion-enabled only -- see script.js):
   the section pins and vertical scroll drives the track's transform directly, so this reads as
   scroll turning into horizontal movement rather than a classic click-through carousel. The
   [data-hscroll] flag is only ever added by JS once GSAP/ScrollTrigger have actually taken over,
   so a page with no GSAP (or reduced-motion) simply keeps the original native horizontal
   scroll + buttons below, unchanged. */
.highlights-sec[data-hscroll]{ overflow:visible; }
.highlights-sec[data-hscroll] .highlights-track-wrap{ overflow:hidden; -webkit-mask-image:none; mask-image:none; }
.highlights-sec[data-hscroll] .highlights-track{ overflow:visible; scroll-snap-type:none; }
.highlights-sec[data-hscroll] .highlights-nav-btns{ display:none; }

.highlight-card{
  position:relative; flex:0 0 278px; scroll-snap-align:start; border-radius:12px; overflow:hidden;
  box-shadow:var(--shadow-md); background:var(--paper); perspective:900px;
  transition:transform .45s var(--ease-premium, cubic-bezier(.22,1,.36,1)), box-shadow .45s ease;
}
@media (max-width:900px){ .highlight-card{ flex:0 0 min(62vw, 340px); } }
@media (max-width:640px){ .highlight-card{ flex:0 0 min(80vw, 320px); } }
.highlight-card:hover{ transform:translateY(-9px) scale(1.015); box-shadow:var(--shadow-lg); z-index:3; }
/* colored gradient ring that blooms in on hover -- cheap, GPU-friendly (opacity only) */
.highlight-card::before{
  content:''; position:absolute; inset:0; z-index:4; border-radius:10px; padding:1.6px; pointer-events:none;
  background:linear-gradient(135deg, var(--butter), var(--rust) 45%, var(--lav-deep) 100%);
  -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite:xor; mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite:exclude;
  opacity:0; transition:opacity .4s ease;
}
.highlight-card:hover::before{ opacity:1; }
.highlight-thumb{ position:relative; aspect-ratio:4/3; background-size:cover; background-position:center; display:flex; align-items:center; justify-content:center; overflow:hidden; transition:transform .6s var(--ease-premium, cubic-bezier(.22,1,.36,1)); }
.highlight-card:hover .highlight-thumb{ transform:scale(1.08) rotate(-.6deg); }
.highlight-scene{ position:absolute; inset:0; width:100%; height:100%; display:block; z-index:0; transition:transform .8s var(--ease-premium, cubic-bezier(.22,1,.36,1)); }
.highlight-card:hover .highlight-scene{ transform:scale(1.05); }
.highlight-card.video .highlight-thumb::after{ content:''; position:absolute; inset:0; z-index:1; background:linear-gradient(180deg,transparent 50%, rgba(22,19,14,.55)); }
/* diagonal shine sweep -- classic premium-card tell, pure CSS, can never get "stuck"
   since it's driven by :hover, not scroll/JS timing */
.highlight-thumb::before{
  content:''; position:absolute; inset:0; z-index:2; pointer-events:none;
  background:linear-gradient(115deg, transparent 38%, rgba(255,255,255,.4) 50%, transparent 62%);
  transform:translateX(-130%); transition:transform .85s cubic-bezier(.2,.8,.2,1);
}
.highlight-card:hover .highlight-thumb::before{ transform:translateX(130%); }
.highlight-play{ position:relative; z-index:2; width:50px; height:50px; border-radius:50%; background:rgba(255,253,246,.94); display:flex; align-items:center; justify-content:center; box-shadow:var(--shadow-md); transition:transform .4s cubic-bezier(.3,1.4,.4,1); }
.highlight-card:hover .highlight-play{ transform:scale(1.2) rotate(10deg); }
.highlight-play svg{ width:16px; height:16px; margin-left:1px; color:var(--ink); }
.highlight-tag{ position:absolute; top:11px; left:11px; z-index:3; background:var(--rust); color:var(--butter); font-size:.66rem; font-weight:800; padding:4px 11px; border-radius:999px; text-transform:uppercase; letter-spacing:.03em; }
.highlight-tag.alt{ background:var(--green-deep); color:var(--butter); }
/* solid background + a hairline light border, not just a translucent dark chip -- the video
   scenes are hand-illustrated and their corners aren't all equally dark, so a see-through
   pill was blending into the artwork and becoming unreadable on some cards (e.g. a dark
   teacup shadow sitting right under it). This reads clearly against any artwork. */
.highlight-dur{ position:absolute; right:11px; bottom:11px; z-index:3; background:#141210; box-shadow:0 0 0 1px rgba(243,238,225,.16), 0 2px 6px rgba(0,0,0,.35); color:var(--paper); font-size:.7rem; font-weight:700; padding:4px 9px; border-radius:7px; }
.highlight-meta{ padding:15px 17px 19px; position:relative; transition:transform .4s var(--ease-premium, cubic-bezier(.22,1,.36,1)); }
.highlight-card:hover .highlight-meta{ transform:translateY(-1px); }
.highlight-meta b{ display:block; font-family:var(--font-display); font-size:1.08rem; font-weight:700; margin-bottom:3px; line-height:1.28; transition:color .3s; }
.highlight-card:hover .highlight-meta b{ color:var(--rust-deep); }
.highlight-meta span{ font-size:.78rem; color:var(--ink-faint); font-weight:600; }
@media (prefers-reduced-motion: reduce){
  .highlight-card, .highlight-thumb, .highlight-scene, .highlight-play, .highlight-thumb::before, .highlight-card::before, .highlight-meta{ transition:none !important; }
  .highlight-card:hover{ transform:none; }
  .highlight-card:hover .highlight-play, .highlight-card:hover .highlight-thumb, .highlight-card:hover .highlight-scene{ transform:none; }
}

/* ---------------- GUEST PANEL (Demlemedeki Konuklar as its own module) ---------------- */
/* Shared box/head styles live here; row/chip interaction rules now live in part4 (see .guests-row-wrap there). */
.guests-panel{ max-width:var(--wrap); margin:34px auto 0; background:var(--paper); border:1px solid var(--line); border-radius:5px; padding:26px 26px 22px; box-shadow:var(--shadow-sm); }
.guests-panel-head{ display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:18px; flex-wrap:wrap; }
