.video-thumb{
  position:relative; aspect-ratio:4/3; border-radius:10px; overflow:hidden; background-size:cover; background-position:center;
  box-shadow:0 18px 40px -20px rgba(22,19,14,.5), 0 2px 0 rgba(243,238,225,.06) inset;
  transition:transform .5s cubic-bezier(.2,.8,.2,1), box-shadow .4s;
}
.video-thumb::before{
  /* premium glass sheen: a soft diagonal highlight sitting above the illustration */
  content:''; position:absolute; inset:0; z-index:1; pointer-events:none;
  background:linear-gradient(122deg, rgba(243,238,225,.16) 0%, rgba(243,238,225,0) 26%, rgba(22,19,14,0) 60%, rgba(22,19,14,.18) 100%);
}
