  /* hairline inner frame -- reads as a considered edge rather than a raw crop */
  content:''; position:absolute; inset:0; z-index:2; pointer-events:none; border-radius:inherit;
  box-shadow:inset 0 0 0 1px rgba(243,238,225,.14);
